# Search for circulant graph on Z_17 with girth >= 6 and many edges
from itertools import combinations

n = 17
def check_girth(edges, n, min_girth):
    # BFS-based girth check
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    girth = float('inf')
    for src in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[src] = 0
        from collections import deque
        q = deque([src])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    # found cycle
                    cyc = dist[u] + dist[v] + 1
                    if cyc < girth:
                        girth = cyc
    return girth

