from collections import deque
import random

def can_add(adj, u, v):
    max_len = 4
    dist = {u:0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_len: continue
        for y in adj[x]:
            if y == v:
                return False
            if y not in dist:
                dist[y] = dist[x]+1
                q.append(y)
    return True

